SELECT
    CAST(
        timezone(
            'UTC',
            TRY_CAST(json_extract_string(resource, '$.onsetDateTime') AS TIMESTAMPTZ)
        ) AS DATE
    ) AS condition_start_date,
    CAST(
        timezone(
            'UTC',
            TRY_CAST(json_extract_string(resource, '$.abatementDateTime') AS TIMESTAMPTZ)
        ) AS DATE
    ) AS condition_stop_date,
    CAST(
        regexp_replace(
            json_extract_string(resource, '$.subject.reference'),
            '^urn:uuid:',
            ''
        ) AS VARCHAR
    ) AS patient_id,
    CAST(
        regexp_replace(
            json_extract_string(resource, '$.context.reference'),
            '^urn:uuid:',
            ''
        ) AS VARCHAR
    ) AS encounter_id,
    CAST(
        json_extract_string(resource, '$.code.coding[0].code') AS VARCHAR
    ) AS condition_code,
    CAST(
        replace(
            json_extract_string(resource, '$.code.coding[0].display'),
            ',',
            ' '
        ) AS VARCHAR
    ) AS condition_description
